let farmView='map';try{farmView=localStorage.getItem('farm-view')||'map'}catch{}
function switchFarmView(view){farmView=view;try{localStorage.setItem('farm-view',view)}catch{}render()}
function openFarmBed(id,tab='grow'){plotRoomTab=tab;if(location.hash==='#bed-'+id){render();return}location.hash='bed-'+id;if(tab!=='grow')setTimeout(()=>{plotRoomTab=tab;render()},0)}
function farmObjectMenu(){rentalCity=selectedFarmCity();location.hash='choose-bed';render()}
function farmUpgradeMenu(){modalForm('Какую грядку улучшить?',`<div class="object-options">${myPlots().map(p=>`<button type="button" class="btn light" onclick="modal.close();openFarmBed(${p.id},'build')">🌱 ${esc(p.name)} · ${p.size} м²</button>`).join('')}</div>`,()=>{})}
function farmBedMenu(id){const p=myPlots().find(p=>p.id===id);if(!p)return;modalForm(esc(p.name),`<p>№${p.id} · ${p.size} м² · ${esc(growingLabels[p.growing_state]||'Нужен осмотр')}</p><p>${simpleNext(p)}</p><div class="map-bed-actions">${[['grow','🌱','Посадить и ухаживать'],['build','🏡','Улучшить грядку'],['camera','📹','Посмотреть камеру'],['harvest','🧺','Собрать урожай'],['activity','📋','Ход работ']].map(([tab,icon,label])=>`<button type="button" class="btn light" onclick="modal.close();openFarmBed(${id},'${tab}')">${icon} ${label}</button>`).join('')}</div><p class="note">Цена и условия доступны перед заказом. Нажатие на объект ничего не списывает.</p>`,()=>{})}
function farmMap(){const plots=typeof cityPlots==='function'?cityPlots():myPlots();return `<section class="farm-world" aria-label="Интерактивная схема моего хозяйства"><div class="farm-world-caption"><span>ВАШ МАЛЕНЬКИЙ МИР</span><h2>Здесь растёт ваше.</h2><p>Нажмите на грядку, чтобы позаботиться о ней.</p></div><div class="farm-cloud" aria-hidden="true"></div><div class="farm-village" aria-hidden="true"><img src="art/house.svg" alt=""><img src="art/warehouse.svg" alt=""><img src="art/house.svg" alt=""></div><div class="farm-grass" aria-hidden="true"></div><div class="farm-fence" aria-hidden="true"></div><div class="farm-tree tree-one" aria-hidden="true"><img src="art/tree.svg" alt=""></div><div class="farm-tree tree-two" aria-hidden="true"><img src="art/tree.svg" alt=""></div><div class="farm-map-objects"><a class="farm-building" href="#settings"><img src="art/house.svg" alt="" aria-hidden="true"><b>Мой дом</b><small>Профиль и финансы</small></a><a class="farm-building" href="#lifecycle"><img src="art/warehouse.svg" alt="" aria-hidden="true"><b>Мой склад</b><small>Урожай и подписка</small></a><a class="farm-building" href="#lifecycle"><img src="art/truck.svg" alt="" aria-hidden="true"><b>Доставка</b><small>Оформить доставку</small></a></div><div class="farm-path" aria-hidden="true"></div><div class="farm-parcels">${plots.map(p=>{const growing=['planted','growing','harvest_ready'].includes(p.growing_state);const jobs=(opsData?.orders||[]).filter(o=>o.plot_id===p.id&&!['done','cancelled'].includes(o.status));return `<button class="farm-parcel ${Number(p.size)>3?'bed-large':'bed-small'} ${growing?'has-plants':'bare-soil'}" onclick="farmBedMenu(${p.id})" aria-label="${esc(p.name)}: ${esc(growingLabels[p.growing_state]||'Нужен осмотр')}. Открыть действия"><span class="parcel-land" aria-hidden="true"><span class="parcel-crops">${Array.from({length:9},()=>`<i>${p.growing_state==='harvest_ready'?'🥬':growing?'🌱':'·'}</i>`).join('')}</span></span><span class="parcel-sign">${esc(p.name)}</span><span class="parcel-status">${jobs.length?'◷ Есть заявка на работу':esc(growingLabels[p.growing_state]||'Нужен осмотр')}</span><span class="parcel-meta">${p.size} м² · №${p.id}</span></button>`}).join('')}<button class="farm-parcel add-parcel" onclick="farmObjectMenu()"><span class="parcel-land" aria-hidden="true"><span class="parcel-plus">＋</span></span><span class="parcel-sign">Новая грядка</span><span class="parcel-status">Выбрать размер</span></button></div><div class="farm-map-footer"><span>🌿 Грядок в хозяйстве: ${plots.length}</span><a href="#orders">Мои заявки →</a></div></section><p class="note">Это схема вашего хозяйства, а не фактический план фермы. Дом и машина — переходы к разделам; хранение требует отдельной подписки. Готовность улучшений подтверждает сотрудник.</p>`}
const listFarmHome=cloudHome;cloudHome=function(){if(!account||!myPlots().length)return listFarmHome();const toggle=`<div class="farm-view-toggle" role="group" aria-label="Вид хозяйства"><button class="btn ${farmView==='map'?'':'light'}" aria-pressed="${farmView==='map'}" onclick="switchFarmView('map')">🌳 Карта</button><button class="btn ${farmView==='list'?'':'light'}" aria-pressed="${farmView==='list'}" onclick="switchFarmView('list')">☷ Список</button></div>`;return farmView==='list'?toggle+listFarmHome():heading('Моё хозяйство','Своя грядка — на расстоянии одного нажатия.',toggle)+farmMap()};render();
